-- Rutinas Pulso Fit; ejecutar tras schema.sql e import:exercises.
-- Casa solo peso corporal. Aire libre: intervalos de caminata/trote y calistenia sencilla.
-- Género no restringe movimientos: objetivo/preferencia ajustan volumen y repeticiones; género solo selecciona la variante solicitada.
begin;
alter table public.exercises alter column source_id drop not null;
alter table public.exercises add column if not exists is_custom boolean not null default false;
insert into public.exercises(id,source_id,is_custom,name,name_es,category,body_part,equipment,target,secondary_muscles,instructions,media_id,media_url,level,place,is_featured) values
('0db72801-ffab-5d4a-8f4b-52c00205a1ff'::uuid,null,true,'Intervalos de caminata y trote · inicio','Intervalos de caminata y trote · inicio','cardio','cardiovascular system','running','cardiovascular system',array['cuádriceps','isquiotibiales','pantorrillas']::text[],array['Elige una ruta plana, iluminada y sin tráfico.','Camina 5 minutos para iniciar.','Alterna 1 minuto de trote suave con 2 minutos de caminata durante 6 rondas.','Mantén un ritmo que te permita hablar en frases cortas.','Camina suavemente 5 minutos al terminar.','Progresión semanal: si completaste las tres sesiones sin dolor ni fatiga excesiva, en la semana siguiente puedes sumar 15 segundos a cada intervalo de trote; si no, repite el mismo nivel.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('b606504b-9fe1-54e7-8d6d-5110dab62086'::uuid,null,true,'Intervalos de caminata y trote · progresión','Intervalos de caminata y trote · progresión','cardio','cardiovascular system','running','cardiovascular system',array['cuádriceps','isquiotibiales','pantorrillas']::text[],array['Comienza con 5 minutos de caminata cómoda.','Alterna 90 segundos de trote suave con 2 minutos de caminata durante 6 rondas.','Si pierdes la capacidad de hablar cómodamente, reduce el trote o camina.','Mantén una zancada natural.','Finaliza con 5 minutos de caminata suave.','Progresión semanal: aumenta solo si terminaste las sesiones anteriores con comodidad; de lo contrario conserva los intervalos actuales.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('a724bc36-e95c-5794-bedc-7e8934ab6152'::uuid,null,true,'Intervalos de caminata y trote · consolidación','Intervalos de caminata y trote · consolidación','cardio','cardiovascular system','running','cardiovascular system',array['cuádriceps','isquiotibiales','pantorrillas']::text[],array['Camina 5 minutos para preparar el cuerpo.','Alterna 2 minutos de trote suave con 2 minutos de caminata durante 6 rondas.','El trote debe sentirse cómodo y controlado.','Si es necesario, vuelve a intervalos de 1 minuto de trote y 2 de caminata.','Camina 5 minutos y recupera la respiración.','Al iniciar una nueva semana, aumenta el trote solo 15 segundos por ronda cuando el nivel actual sea cómodo; nunca avances si aparece dolor.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('56cbc467-ef50-5f9c-a13e-c3947d69eb0d'::uuid,null,true,'Caminata activa de recuperación','Caminata activa de recuperación','cardio','cardiovascular system','body weight','cardiovascular system',array['pantorrillas','cuádriceps']::text[],array['Camina 20 minutos en una ruta segura y plana.','Mantén un ritmo cómodo que permita conversar.','Relaja hombros y brazos.','Reduce el ritmo si aparece fatiga fuera de lo habitual.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('7816ce86-5e04-5070-811f-df2136027aa2'::uuid,null,true,'Caminata suave y movilidad','Caminata suave y movilidad','cardio','cardiovascular system','body weight','cardiovascular system',array['pantorrillas','caderas']::text[],array['Camina suavemente durante 25 minutos.','El propósito es recuperar y mantener el hábito, no buscar velocidad.','Al terminar, realiza movilidad suave de tobillos y caderas.','Detente si aparece dolor, mareo o malestar.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('c696128d-c444-5039-b5aa-ab4479c0c4ca'::uuid,null,true,'Sentadilla con peso corporal en parque','Sentadilla con peso corporal en parque','upper legs','quads','body weight','quads',array['cuádriceps','glúteos','isquiotibiales']::text[],array['Párate con los pies aproximadamente al ancho de los hombros.','Lleva las caderas hacia atrás y flexiona las rodillas hasta un rango cómodo.','Mantén el pecho abierto y las rodillas alineadas con los pies.','Empuja el suelo para volver a ponerte de pie.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('7253ef5b-69d7-56ac-8fce-e3d97851e10a'::uuid,null,true,'Flexión inclinada en banca estable','Flexión inclinada en banca estable','chest','pectorals','body weight','pectorals',array['pectorales','tríceps','hombros']::text[],array['Apoya las manos sobre una banca fija y estable, un poco más separadas que los hombros.','Camina con los pies hacia atrás hasta formar una línea cómoda entre cabeza, cadera y talones.','Flexiona los codos y acerca el pecho a la banca manteniendo el abdomen activo.','Empuja con las manos para volver a la posición inicial.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('3256ad39-9799-52ed-b1e3-1ea62be302b2'::uuid,null,true,'Plancha frontal en superficie estable','Plancha frontal en superficie estable','waist','abs','body weight','abs',array['abdominales','hombros','glúteos']::text[],array['Apoya antebrazos y puntas de los pies sobre una superficie limpia y estable.','Alinea hombros, cadera y tobillos; evita hundir la zona lumbar.','Activa abdomen y glúteos y respira con normalidad.','Mantén 15 a 30 segundos; reduce el tiempo si pierdes la postura.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('0d245bf8-b3e7-5d38-b856-6b764d620ae5'::uuid,null,true,'Zancada alterna con peso corporal','Zancada alterna con peso corporal','upper legs','quads','body weight','quads',array['cuádriceps','glúteos','isquiotibiales']::text[],array['Párate erguido sobre una superficie plana.','Da un paso cómodo hacia adelante y flexiona ambas rodillas sin forzar el rango.','Mantén el tronco estable y la rodilla delantera alineada con el pie.','Empuja con el pie delantero para volver y alterna el lado.']::text[],null,null,'principiante',array['aire_libre']::text[],false),
('041eed1e-4aa7-5839-a081-060681e77fec'::uuid,null,true,'Extensión alterna de brazo y pierna','Extensión alterna de brazo y pierna','waist','abs','body weight','abs',array['zona media','glúteos','espalda']::text[],array['Colócate en cuatro apoyos sobre una esterilla o superficie limpia.','Extiende lentamente el brazo derecho y la pierna izquierda sin girar la cadera.','Mantén un instante y vuelve con control.','Alterna los lados manteniendo la espalda neutra.']::text[],null,null,'principiante',array['aire_libre']::text[],false)
on conflict(id) do update set name=excluded.name,name_es=excluded.name_es,category=excluded.category,body_part=excluded.body_part,equipment=excluded.equipment,target=excluded.target,secondary_muscles=excluded.secondary_muscles,instructions=excluded.instructions,place=excluded.place,is_custom=true;
-- Elimina plantillas anteriores para que una nueva ejecución deje exactamente 60 combinaciones.
delete from public.routines;
insert into public.routines(gender,routine_preference,goal,place,title)
select g.gender,p.preference,go.goal,pl.place,'Plan '||g.gender||' · '||go.goal||' · '||pl.place||coalesce(' · '||p.preference,'')
from (values ('hombre'),('mujer'),('prefiero_no_decirlo')) g(gender)
cross join (values ('bajar_peso'),('mantener'),('subir_peso'),('ganar_masa_muscular')) go(goal)
cross join (values ('gimnasio'),('casa'),('aire_libre')) pl(place)
cross join lateral (select unnest(case when g.gender='prefiero_no_decirlo' then array['fuerza','tonificacion','equilibrada']::text[] else array[null::text] end) preference) p
on conflict (gender,routine_preference,goal,place) do update set title=excluded.title;
delete from public.routine_days d using public.routines r where r.id=d.routine_id;
with days(weekday,focus) as (values ('lunes','Tren superior · empuje'),('martes','Piernas y glúteos'),('miercoles','Espalda y brazos'),('jueves','Zona media y resistencia'),('viernes','Cuerpo completo')) insert into public.routine_days(routine_id,weekday,focus,warmup,cooldown) select r.id,d.weekday,case when r.place='aire_libre' then case d.weekday when 'lunes' then 'Intervalos iniciales y ejercicios de parque' when 'martes' then 'Caminata de recuperación y movilidad' when 'miercoles' then 'Intervalos en progresión y parque' when 'jueves' then 'Caminata suave y movilidad' else 'Intervalos de consolidación y parque' end else d.focus end,case r.place when 'gimnasio' then '[{"name": "Bicicleta o caminadora suave", "duration": "4 minutos", "steps": "Aumenta el ritmo gradualmente, sin agotarte."}, {"name": "Círculos de hombros", "duration": "10 por dirección", "steps": "Haz círculos controlados sin forzar el cuello."}, {"name": "Movilidad de cadera", "duration": "8 por lado", "steps": "Realiza aperturas de cadera lentas."}, {"name": "Sentadillas sin carga", "duration": "10 repeticiones", "steps": "Mantén las rodillas alineadas con los pies."}, {"name": "Series de aproximación", "duration": "1–2 series ligeras", "steps": "Ensaya el primer ejercicio con poca carga."}]'::jsonb when 'casa' then '[{"name": "Marcha en el sitio", "duration": "3 minutos", "steps": "Eleva los pies de forma alterna."}, {"name": "Círculos de hombros", "duration": "10 por dirección", "steps": "Muévete suavemente."}, {"name": "Movilidad de tobillos", "duration": "10 por lado", "steps": "Rota cada tobillo lentamente."}, {"name": "Bisagra de cadera", "duration": "10 repeticiones", "steps": "Lleva las caderas atrás con espalda larga."}, {"name": "Sentadillas cómodas", "duration": "8–10 repeticiones", "steps": "Usa peso corporal y rango sin dolor."}]'::jsonb when 'aire_libre' then '[{"name": "Caminata suave", "duration": "5 minutos", "steps": "Empieza sobre una ruta plana y segura."}, {"name": "Movilidad de tobillos", "duration": "10 por lado", "steps": "Haz círculos lentos."}, {"name": "Balanceo de piernas", "duration": "8 por lado", "steps": "Sujétate de un apoyo y balancea corto."}, {"name": "Marcha activa", "duration": "60 segundos", "steps": "Aumenta el ritmo sin correr."}, {"name": "Movilidad de cadera", "duration": "8 por lado", "steps": "Realiza aperturas sin rebotes."}]'::jsonb else '[]'::jsonb end,case r.place when 'gimnasio' then '[{"name": "Caminata lenta", "duration": "2 minutos", "steps": "Reduce el ritmo poco a poco."}, {"name": "Estiramiento de pectoral", "duration": "20 s por lado", "steps": "Apoya el antebrazo y gira suavemente el torso."}, {"name": "Estiramiento de cuádriceps", "duration": "20 s por lado", "steps": "Sujeta el tobillo sin forzar."}, {"name": "Estiramiento de espalda", "duration": "20–30 s", "steps": "Lleva las manos al frente y relaja la espalda."}, {"name": "Respiración tranquila", "duration": "5 ciclos", "steps": "Inhala y exhala lentamente."}]'::jsonb when 'casa' then '[{"name": "Marcha lenta", "duration": "2 minutos", "steps": "Baja la intensidad de forma gradual."}, {"name": "Estiramiento de pantorrilla", "duration": "20 s por lado", "steps": "Lleva una pierna atrás y apoya el talón."}, {"name": "Estiramiento de muslo anterior", "duration": "20 s por lado", "steps": "Sujeta el tobillo con apoyo."}, {"name": "Estiramiento de glúteos", "duration": "20 s por lado", "steps": "Cruza un tobillo sobre la rodilla opuesta."}, {"name": "Respiración diafragmática", "duration": "5 ciclos", "steps": "Relaja hombros y respira sin prisa."}]'::jsonb when 'aire_libre' then '[{"name": "Caminata muy suave", "duration": "5 minutos", "steps": "Recupera una respiración cómoda."}, {"name": "Estiramiento de pantorrilla", "duration": "20 s por lado", "steps": "Apoya las manos en una superficie estable."}, {"name": "Estiramiento de cuádriceps", "duration": "20 s por lado", "steps": "Sujeta un apoyo y acerca el talón al glúteo."}, {"name": "Estiramiento de isquiotibiales", "duration": "20 s por lado", "steps": "Apoya el talón y flexiona la cadera."}, {"name": "Respiración y relajación", "duration": "5 ciclos", "steps": "Inhala y exhala despacio."}]'::jsonb else '[]'::jsonb end from public.routines r cross join days d;
do $$
declare r record; d record; ex record; targets text[]; nsets integer; park_sets integer; reps_text text; rest_s integer; pos integer; run_name text;
begin
 for r in select * from public.routines loop
  if r.goal in ('subir_peso','ganar_masa_muscular') or r.routine_preference='fuerza' then nsets:=4; reps_text:='8–10'; rest_s:=90;
  elsif r.goal='bajar_peso' or r.routine_preference='tonificacion' then nsets:=3; reps_text:='12–15'; rest_s:=60;
  else nsets:=3; reps_text:='10–12'; rest_s:=75; end if;
  park_sets:=case when nsets=4 then 3 else 2 end;
  for d in select * from public.routine_days where routine_id=r.id order by case weekday when 'lunes' then 1 when 'martes' then 2 when 'miercoles' then 3 when 'jueves' then 4 else 5 end loop
   if r.place='aire_libre' then
    run_name:=case d.weekday when 'lunes' then 'Intervalos de caminata y trote · inicio' when 'miercoles' then 'Intervalos de caminata y trote · progresión' when 'viernes' then 'Intervalos de caminata y trote · consolidación' when 'martes' then 'Caminata activa de recuperación' else 'Caminata suave y movilidad' end;
    select id into ex from public.exercises where is_custom and name=run_name limit 1;
    insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,1,case d.weekday when 'lunes' then '6 rondas: 1 min trote + 2 min caminata' when 'miercoles' then '6 rondas: 90 s trote + 2 min caminata' when 'viernes' then '6 rondas: 2 min trote + 2 min caminata' when 'martes' then '20 minutos cómodos' else '25 minutos suaves' end,60,1);
    if d.weekday in ('lunes','miercoles','viernes') then
      select id into ex from public.exercises where is_custom and name='Sentadilla con peso corporal en parque' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,reps_text,rest_s,2);
      select id into ex from public.exercises where is_custom and name='Flexión inclinada en banca estable' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,reps_text,rest_s,3);
    elsif d.weekday='martes' then
      select id into ex from public.exercises where is_custom and name='Plancha frontal en superficie estable' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,'15–30 segundos',45,2);
      select id into ex from public.exercises where is_custom and name='Zancada alterna con peso corporal' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,reps_text,rest_s,3);
    else
      select id into ex from public.exercises where is_custom and name='Extensión alterna de brazo y pierna' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,reps_text,rest_s,2);
      select id into ex from public.exercises where is_custom and name='Plancha frontal en superficie estable' limit 1;
      insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,park_sets,'15–20 segundos',45,3);
    end if;
   else
    targets:=case d.weekday when 'lunes' then array['pectorals','delts','triceps'] when 'martes' then array['glutes','quads','hamstrings','calves'] when 'miercoles' then array['lats','upper back','biceps','traps'] when 'jueves' then array['abs','cardiovascular system','obliques'] else array['pectorals','glutes','lats','abs','quads','delts'] end;
    pos:=0;
    for ex in select e.id from public.exercises e where e.is_featured and not e.is_custom and ((r.place='casa' and lower(coalesce(e.equipment,''))='body weight') or (r.place='gimnasio' and e.place @> array['gimnasio']::text[])) order by case when e.target=any(targets) then 0 else 1 end,md5(e.source_id||r.gender||r.goal||coalesce(r.routine_preference,'')||d.weekday) limit 4 loop
     pos:=pos+1;
     insert into public.routine_exercises(routine_day_id,exercise_id,sets,reps,rest_seconds,order_index) values(d.id,ex.id,nsets,reps_text,rest_s,pos);
    end loop;
    if pos<>4 then raise exception 'No hay cuatro ejercicios para la rutina %, día %',r.id,d.weekday; end if;
   end if;
  end loop;
 end loop;
end $$;
commit;